// illustrative — the honest placeholder.
//
// PLAN D5 draws a hard line: AI image generation (NB Pro / Canva) is for
// *illustrative art only*, cached under a stable key, and it is NOT part of this
// engine. So when an author asks for a picture that is decoration rather than
// information, we do not silently invent one and we do not leave a blank box —
// we render a labelled slot that says what art is wanted and what key it will be
// cached under, so the gap is visible in review instead of shipping unnoticed.
//
// It is also the safety net for a spec the pipeline could not fulfil: pass
// `reason` and the page shows why.

const { Svg, C, SIZE, LEADING, wrap } = require("../lib/svg");

function render(spec) {
  const lang = spec.lang;
  const isUr = lang === "ur";
  const w = spec.width ?? 560;
  const bodyH = spec.height ?? 190;

  const svg = new Svg(w, bodyH, {
    title: spec.title,
    caption: spec.caption,
    source: spec.source,
    note: spec.note,
    lang,
    spec,
  });

  svg.rect(2, 2, w - 4, bodyH - 4, {
    rx: 10,
    fill: "#F6F8FC",
    stroke: C.rule,
    sw: 2,
    dash: "8 6",
  });

  // A small picture glyph, so it reads as "art goes here" at a glance.
  const gx = w / 2;
  const gy = 46;
  svg.rect(gx - 27, gy - 20, 54, 40, { rx: 4, fill: "none", stroke: C.faint, sw: 2 });
  svg.circle(gx - 12, gy - 8, 4.5, { fill: C.faint });
  svg.polyline(
    [
      [gx - 23, gy + 16],
      [gx - 6, gy - 2],
      [gx + 4, gy + 8],
      [gx + 13, gy - 1],
      [gx + 23, gy + 16],
    ],
    { stroke: C.faint, sw: 2, fill: "none" }
  );

  const kind = String(spec.kind || spec.subject || "illustrative art").toUpperCase();
  svg.text(w / 2, gy + 44, kind, {
    size: SIZE.small,
    weight: 700,
    anchor: "middle",
    fill: C.ink,
    letterSpacing: "0.12em",
  });

  const brief = spec.brief || spec.alt || spec.reason || "illustrative artwork — not generated by this engine";
  const size = SIZE.small;
  const lh = size * (isUr ? LEADING.urdu : LEADING.latin);
  if (isUr) {
    svg.textBlock(24, gy + 58, w - 48, brief, { size, lang, fill: C.muted });
  } else {
    wrap(brief, size, w - 60).slice(0, 3).forEach((ln, i) =>
      svg.text(w / 2, gy + 70 + i * lh, ln, { size, anchor: "middle", fill: C.muted })
    );
  }

  if (spec.key) {
    svg.text(w / 2, bodyH - 16, `cache key: ${spec.key}`, {
      size: SIZE.tiny,
      anchor: "middle",
      fill: C.faint,
      family: "'SF Mono', Consolas, monospace",
    });
  } else {
    svg.text(w / 2, bodyH - 16, "AI art is out of scope for the diagram engine (PLAN D5)", {
      size: SIZE.tiny,
      anchor: "middle",
      fill: C.accent,
      weight: 700,
    });
  }

  return svg.toString();
}

module.exports = {
  type: "illustrative",
  aliases: ["ai_art", "placeholder"],
  summary:
    "Placeholder slot for illustrative (non-informational) art, which this engine deliberately does not generate — shows the brief and its cache key rather than a blank box.",
  render,
  examples: [
    {
      name: "illustrative_placeholder",
      spec: {
        type: "illustrative",
        kind: "chapter opener",
        title: "Village water tank at dusk",
        brief:
          "A warm, flat-vector village scene: a raised water tank, a few houses, no people, no text anywhere in the image.",
        key: "g7_sci_u1_opener_v1",
        caption: "Decoration only — nothing in this picture is assessed.",
      },
    },
    {
      name: "illustrative_unavailable",
      spec: {
        type: "illustrative",
        kind: "unavailable",
        title: "Figure not located",
        reason:
          "The figure-locator could not verify a crop for this block on p.48, so no textbook figure is shown.",
      },
    },
  ],
};
